parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const project_id = (body.project_id || '').trim();
if (!project_id) throw new Error('project_id is required');
return [{ json: { project_id } }];

// Extract client_code from project record to fetch the brief
const project = $input.first().json;
const client_code = project.client_code || (project.fields && project.fields.client_code) || '';
const project_id = $('Extract Project ID').first().json.project_id;
if (!client_code) throw new Error('No client_code found in project record');
return [{ json: { client_code, project_id, project } }];

// ============================================================
// Merge all data sources and build the Writer Prompt
// Only includes approved concepts (NOT all concepts)
// ============================================================

const projectData = $('Extract Client Code').first().json;
const project_id = projectData.project_id;
const project = projectData.project;

// Helper to unpack HTTP Request Airtable responses ({records:[...]}) into individual items
function unpackRecords(nodeItems) {
  if (nodeItems.length === 1 && nodeItems[0].json.records) {
    return nodeItems[0].json.records.map(r => ({ json: { id: r.id, ...r.fields } }));
  }
  return nodeItems;
}

// Get approved concepts
const approvedConcepts = unpackRecords($('Fetch Approved Concepts').all()).map(item => {
  const d = item.json;
  return {
    id: d.id,
    concept_name: d.concept_name || d.fields?.concept_name || 'Unnamed',
    framework: d.framework || d.fields?.framework || 'PAS',
    hook_type: d.hook_type || d.fields?.hook_type || 'curiosity-gap',
    hook_text: d.hook_text || d.fields?.hook_text || '',
    format: d.format || d.fields?.format || 'Talking Head',
    funnel_stage: d.funnel_stage || d.fields?.funnel_stage || 'TOF',
    virality_score: d.virality_score || d.fields?.virality_score || 5,
    concept_pitch: d.concept_pitch || d.fields?.concept_pitch || '',
    emotional_journey: d.emotional_journey || d.fields?.emotional_journey || '',
    target_objection: d.target_objection || d.fields?.target_objection || '',
    platform: d.platform || d.fields?.platform || 'TikTok'
  };
});

// Get research data
const researchRecords = unpackRecords($('Fetch Research Data').all()).map(item => {
  const d = item.json;
  return {
    type: d.research_type || d.fields?.research_type || '',
    category: d.category || d.fields?.category || '',
    content: d.content || d.fields?.content || '',
    source: d.source || d.fields?.source || ''
  };
});

// Get reference videos
const refRecords = unpackRecords($('Fetch Reference Videos').all()).map(item => {
  const d = item.json;
  return {
    url: d.url || d.fields?.url || '',
    platform: d.platform || d.fields?.platform || '',
    format: d.format || d.fields?.format || '',
    hook: d.hook || d.fields?.hook || '',
    why_it_works: d.why_it_works || d.fields?.why_it_works || '',
    adaptation_idea: d.adaptation_idea || d.fields?.adaptation_idea || ''
  };
});

// Get Script Library examples for reference
let libraryScripts = [];
try {
  const libRaw = $('Fetch Script Library').all();
  const libRecords = (libRaw.length === 1 && libRaw[0].json.records)
    ? libRaw[0].json.records.map(r => ({ ...r.fields, id: r.id }))
    : libRaw.map(item => item.json);
  libraryScripts = libRecords.filter(s => s.full_script && s.full_script.length > 50).map(s => ({
    ...s,
    industry: s.category || '',
    hook_text: s.hook || ''
  }));
} catch(e) {
  // Script Library not available, continue without it
}

// Get Reference Ads for inspiration
let referenceAds = [];
try {
  const refAdRaw = $('Fetch Reference Ads').all();
  const refAdRecords = (refAdRaw.length === 1 && refAdRaw[0].json.records)
    ? refAdRaw[0].json.records.map(r => ({ ...r.fields, id: r.id }))
    : refAdRaw.map(item => item.json);
  referenceAds = refAdRecords.filter(a => a.ad_name || a.hook_text).map(a => ({
    ad_name: a.ad_name || '',
    brand_name: a.brand_name || '',
    industry: a.industry || '',
    platform: a.platform || '',
    format: a.format || '',
    hook_text: a.hook_text || '',
    ad_copy: a.ad_copy || '',
    why_it_works: a.why_it_works || '',
    performance: a.performance || '',
    metrics: a.metrics || ''
  }));
} catch(e) {
  // Reference Ads not available, continue without
}

// Get live ad performance metrics from Meta
let livePerformanceSection = '';
try {
  const liveMetricsRaw = $('Fetch Live Metrics').first().json;
  const liveAds = (liveMetricsRaw.data || []);
  if (liveAds.length > 0) {
    let totalSpend = 0, totalClicks = 0, totalImpr = 0, totalPurchases = 0, totalRevenue = 0;
    const adSummaries = liveAds.map(ad => {
      const spend = parseFloat(ad.spend || 0);
      const clicks = parseInt(ad.clicks || 0);
      const impr = parseInt(ad.impressions || 0);
      const ctr = parseFloat(ad.ctr || 0);
      const cpc = parseFloat(ad.cpc || 0);
      const actions = ad.actions || [];
      const actionValues = ad.action_values || [];
      const purchases = parseInt((actions.find(a => a.action_type === 'purchase') || {}).value || 0);
      const revenue = parseFloat((actionValues.find(a => a.action_type === 'purchase') || {}).value || 0);
      const roas = spend > 0 ? (revenue / spend).toFixed(2) : '0.00';
      totalSpend += spend;
      totalClicks += clicks;
      totalImpr += impr;
      totalPurchases += purchases;
      totalRevenue += revenue;
      return `- ${ad.ad_name}: Spend $${spend.toFixed(0)}, CTR ${ctr.toFixed(2)}%, CPC $${cpc.toFixed(2)}, ROAS ${roas}x, Purchases ${purchases}`;
    });
    const avgCTR = totalImpr > 0 ? ((totalClicks / totalImpr) * 100).toFixed(2) : '0.00';
    const avgCPC = totalClicks > 0 ? (totalSpend / totalClicks).toFixed(2) : '0.00';
    const overallROAS = totalSpend > 0 ? (totalRevenue / totalSpend).toFixed(2) : '0.00';
    livePerformanceSection = `== LIVE AD PERFORMANCE (Last 14 Days) ==
ACCOUNT BENCHMARKS: Avg CTR ${avgCTR}%, Avg CPC $${avgCPC}, Overall ROAS ${overallROAS}x
Total: $${totalSpend.toFixed(0)} spent, ${totalPurchases} purchases, $${totalRevenue.toFixed(0)} revenue

TOP ADS BY SPEND:
${adSummaries.join('\n')}

INSIGHTS FOR WRITER:
- Target CTR above ${avgCTR}% (account average)
- Scripts should aim for hooks that outperform current CPC of $${avgCPC}
- Focus on angles/hooks similar to the top performing ads above
- Current ROAS is ${overallROAS}x — aim for scripts that can beat this benchmark`;
  }
} catch(e) {
  // Live metrics not available, continue without
}


// Build brief from Google Sheets
let brief = {};
try {
  const row = $('Fetch Client Brief').first().json;
  function c(v) { return v === undefined || v === null ? '' : String(v).trim(); }
  brief = {
    client_code: c(row.client_code),
    brand_name: c(row.brand_name),
    client_name: c(row.client_name),
    client_email: c(row.client_email),
    product_feature: c(row.product_feature),
    differentiator: c(row.differentiator),
    target_user: c(row.target_user),
    biggest_problem: c(row.biggest_problem),
    main_hesitation: c(row.main_hesitation),
    selling_proposition: c(row.selling_proposition),
    brand_personality: c(row.brand_personality),
    credibility_point: c(row.credibility_point),
    transformation: c(row.transformation),
    social_proof: c(row.social_proof),
    compliance: c(row.compliance),
    do_not_say: c(row.do_not_say),
    additional_notes: c(row.additional_notes),
    num_scripts: parseInt(c(row.num_scripts)) || 3
  };
} catch(e) {
  // Use project data as fallback
  brief = {
    brand_name: project.brand_name || project.fields?.brand_name || 'Brand',
    client_code: project.client_code || project.fields?.client_code || '',
    client_name: project.client_name || project.fields?.client_name || '',
    num_scripts: project.num_scripts || project.fields?.num_scripts || 3
  };
}

// Extract Fireflies call context if available
let callContextSection = '';
try {
  const rawCallContext = project.call_context || project.fields?.call_context || '';
  if (rawCallContext && rawCallContext.length > 10) {
    let parsed;
    try { parsed = JSON.parse(rawCallContext); } catch(e) { parsed = null; }
    if (parsed) {
      const parts = [];
      if (parsed.brand_goals) parts.push(`Brand Goals: ${parsed.brand_goals}`);
      if (parsed.content_preferences) parts.push(`Content Preferences: ${parsed.content_preferences}`);
      if (parsed.target_audience_insights) parts.push(`Target Audience Insights: ${parsed.target_audience_insights}`);
      if (parsed.pain_points) parts.push(`Pain Points: ${parsed.pain_points}`);
      if (parsed.tone_and_style) parts.push(`Tone & Style: ${parsed.tone_and_style}`);
      if (parsed.competitor_mentions) parts.push(`Competitor Mentions: ${parsed.competitor_mentions}`);
      if (parsed.budget_and_scale) parts.push(`Budget & Scale: ${parsed.budget_and_scale}`);
      if (parsed.key_phrases) parts.push(`Key Phrases to Use: ${Array.isArray(parsed.key_phrases) ? parsed.key_phrases.join(', ') : parsed.key_phrases}`);
      if (parsed.additional_context) parts.push(`Additional Context: ${parsed.additional_context}`);
      if (parts.length > 0) callContextSection = parts.join('\n');
    } else {
      callContextSection = rawCallContext;
    }
  }
} catch(e) { /* no call context */ }

// Build research summary text
const researchSummary = researchRecords.map(r => 
  `[${r.type}] (${r.source} | ${r.category}): ${r.content}`
).join('\n');

// Build reference summary text
const refSummary = refRecords.map(r =>
  `- ${r.platform} (${r.format}): ${r.url}\n  Hook: ${r.hook}\n  Why: ${r.why_it_works}\n  Adaptation: ${r.adaptation_idea}`
).join('\n\n');

// Build concept deck
const conceptDeck = approvedConcepts.map((c, i) =>
  `CONCEPT ${i + 1}: ${c.concept_name}\n  Framework: ${c.framework} | Hook Type: ${c.hook_type} | Format: ${c.format}\n  Funnel: ${c.funnel_stage} | Platform: ${c.platform} | Virality: ${c.virality_score}/10\n  Hook: "${c.hook_text}"\n  Pitch: ${c.concept_pitch}\n  Emotional Journey: ${c.emotional_journey}\n  Target Objection: ${c.target_objection}`
).join('\n\n');


// Match industry and select top reference scripts from library
const industryKeywords = {
  'Skincare & Beauty': ['skin', 'skincare', 'beauty', 'cosmetic', 'face', 'serum', 'cream', 'glow', 'acne', 'moistur'],
  'Automotive': ['car', 'auto', 'vehicle', 'wash', 'detailing', 'wheel', 'tire', 'motor', 'drive'],
  'Wellness & Ayurveda': ['ayurved', 'wellness', 'herbal', 'natural', 'holistic', 'herb'],
  'Health & Wellness': ['health', 'fitness', 'supplement', 'vitamin', 'protein', 'workout', 'gym', 'weight'],
  'Tech & Electronics': ['tech', 'electronic', 'gadget', 'device', 'app', 'software', 'phone', 'smart'],
  'Food & Beverage': ['food', 'drink', 'beverage', 'snack', 'coffee', 'tea', 'juice', 'eat'],
  'Home Services': ['home', 'clean', 'service', 'plumb', 'repair', 'house'],
  'Fintech': ['fintech', 'finance', 'bank', 'payment', 'invest', 'insurance', 'loan', 'credit', 'money'],
  'Fashion & Apparel': ['fashion', 'cloth', 'apparel', 'wear', 'dress', 'shoe', 'accessory', 'style']
};

// Detect client industry from brief
let detectedIndustry = '';
const briefText = [brief.brand_name, brief.product_feature, brief.target_user, brief.biggest_problem, brief.differentiator].join(' ').toLowerCase();
let bestScore = 0;
for (const [industry, keywords] of Object.entries(industryKeywords)) {
  const score = keywords.filter(kw => briefText.includes(kw)).length;
  if (score > bestScore) {
    bestScore = score;
    detectedIndustry = industry;
  }
}

// Select top 3 reference scripts — prioritize same industry, then diverse
let selectedScripts = [];
if (libraryScripts.length > 0) {
  const sameIndustry = libraryScripts.filter(s => s.industry === detectedIndustry);
  const otherIndustry = libraryScripts.filter(s => s.industry !== detectedIndustry);

  // Take up to 2 from same industry
  selectedScripts = sameIndustry.slice(0, 2);
  // Fill remaining from other industries for diversity
  const remaining = 3 - selectedScripts.length;
  if (remaining > 0) {
    // Pick from different industries for diversity
    const seen = new Set();
    for (const s of otherIndustry) {
      if (!seen.has(s.industry)) {
        selectedScripts.push(s);
        seen.add(s.industry);
        if (selectedScripts.length >= 3) break;
      }
    }
  }
}

// Build reference scripts section
let refScriptsSection = '';
if (selectedScripts.length > 0) {
  refScriptsSection = selectedScripts.map((s, i) => {
    const scriptPreview = (s.full_script || '').substring(0, 500);
    const hookText = s.hook_text || 'N/A';
    return `REFERENCE ${i + 1}: "${s.brand_name}" (${s.industry})
  Format: ${s.format || 'N/A'} | Framework: ${s.framework || 'N/A'} | Hook Type: ${s.hook_type || 'N/A'}
  Hook: "${hookText}"
  Script Preview: "${scriptPreview}..."
  Costumes: ${s.costumes || 'N/A'}
  Props: ${s.props || 'N/A'}`;
  }).join('\n\n');
}

const numConcepts = approvedConcepts.length;

const prompt = `Write COMPLETE UGC scripts for the ${numConcepts} CLIENT-APPROVED concepts below.

These concepts have been reviewed and approved by the PM and the client. Write full scripts for ALL of them.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature || 'N/A'}
Differentiator: ${brief.differentiator || 'N/A'}
Selling Proposition: ${brief.selling_proposition || 'N/A'}
Target: ${brief.target_user || 'N/A'}
Problem: ${brief.biggest_problem || 'N/A'}
Hesitation: ${brief.main_hesitation || 'N/A'}
Transformation: ${brief.transformation || 'N/A'}
Personality: ${brief.brand_personality || 'N/A'}
Credibility: ${brief.credibility_point || 'N/A'}
Social Proof: ${brief.social_proof || 'N/A'}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}
Notes: ${brief.additional_notes || 'None'}

${callContextSection ? `== CLIENT CALL CONTEXT (from onboarding call) ==
${callContextSection}

` : ''}== RESEARCH INSIGHTS ==
${researchSummary || 'Research data available in Airtable.'}

== REFERENCE VIDEOS/ADS ==
${refSummary || 'Reference videos available in Airtable.'}

== APPROVED CONCEPT DECK ==
${conceptDeck}

== INDUSTRY CONTEXT ==
Detected Industry: ${detectedIndustry || 'General'}
Adapt your tone, vocabulary, visual style, and creator voice to match this industry's conventions. Refer to the INDUSTRY-SPECIFIC GUIDELINES in your system prompt.

${refScriptsSection ? `== REFERENCE SCRIPTS FROM YOUR LIBRARY ==
These are REAL scripts from your agency's past work. Study their hook style, tone, pacing, structure, and costume/prop specificity. Use them as quality benchmarks — your output should be AT LEAST this good.
${detectedIndustry ? `Detected client industry: ${detectedIndustry}` : ''}

${refScriptsSection}

IMPORTANT: Do NOT copy these scripts. Use them as INSPIRATION for tone, structure, and specificity. Adapt the quality level to the current client's brand.
` : ''}

${livePerformanceSection ? livePerformanceSection + '\n\n' : ''}== REFERENCE ADS (REAL PERFORMANCE DATA) ==
${referenceAds.length > 0 ? referenceAds.map(a => 
  `Ad: ${a.ad_name} (${a.brand_name} | ${a.industry})
Platform: ${a.platform} | Format: ${a.format}
Hook: ${a.hook_text}
Copy: ${a.ad_copy}
Performance: ${a.performance} ${a.metrics ? '— ' + a.metrics : ''}
Why it works: ${a.why_it_works}
---`
).join('\n') : 'No reference ads available.'}

== OUTPUT FORMAT ==
For EACH concept (all ${numConcepts}), output this JSON structure:
{
  "scripts": [
    {
      "script_number": 1,
      "concept_name": "from concept deck above",
      "concept_id": "will be matched later",
      "framework_used": "PAS / BAB / AIDA / etc.",
      "hook_type": "controversy / POV / calling-out / etc.",
      "funnel_stage": "TOF / MOF / BOF",
      "format": "the UGC format",
      "platform": "TikTok / Reels / Facebook",
      "hooks": [
        "Hook variation 1 — exact opening words (strongest)",
        "Hook variation 2 — different angle on same concept",
        "Hook variation 3 — different energy on same concept"
      ],
      "concept_story": "1-2 sentence concept pitch for the brief header",
      "costumes": [
        { "item": "Oversized beige blazer", "reference_link": "https://pinterest.com/search/pins/?q=oversized+beige+blazer" }
      ],
      "props": ["Product box", "Ring light", "Coffee mug"],
      "references": [
        { "description": "Close-up product demo style — energetic reveal", "link": "" }
      ],
      "creative_table": [
        {
          "scene": 1,
          "voiceover": "Opening line — hook delivery",
          "visuals": "Close-up of creator, direct to camera, natural lighting",
          "references": "[Style: close-up, direct to camera, natural lighting]"
        },
        { "scene": 2, "voiceover": "...", "visuals": "...", "references": "..." }
      ],
      "full_script": "Complete script as creator would say it",
      "estimated_duration": "25 sec",
      "hook": "Primary hook (same as hooks[0])",
      "hook_reinforcement": "Second line that keeps them watching (3-5 sec)",
      "problem": "Relate to viewer (5-10 sec)",
      "solution": "Natural product discovery (10-18 sec)",
      "proof": "Specific proof points (18-25 sec)",
      "cta": "Curiosity-driven close (25-30 sec)",
      "visual_direction": "Overall direction summary",
      "on_screen_text": ["Overlay 1", "Overlay 2"],
      "creator_notes": "Tone, energy, pacing",
      "thumbnail_frame": "Description of first frame"
    }
  ]
}

CRITICAL REQUIREMENTS:
- 'hooks' array MUST have exactly 3 variations (different angle, different energy)
- 'creative_table' MUST have 4-7 scenes with voiceover, visuals, and references per scene
- 'costumes' MUST list specific wardrobe items. reference_link MUST be a Pinterest SEARCH URL in this EXACT format: https://pinterest.com/search/pins/?q=item+description (replace spaces with +). NEVER use pinterest.com/pin/ URLs — those are hallucinated.
- 'references' array: set "link" to empty string "". Do NOT invent URLs for TikTok, Instagram, Meta, or any platform.
- 'creative_table' references field: use ONLY descriptive text in brackets like "[Style: close-up product demo]". NEVER put any URL in this field.
- 'props' MUST list all physical items needed to film
- 'concept_story' is a 1-2 sentence concept pitch for the production brief header
- 'full_script' must sound like a REAL PERSON with filler words, reactions, pauses [beat]
- 'hook' field should equal hooks[0]

⚠️ URL RULES (STRICTLY ENFORCED):
1. Pinterest costume links: ONLY https://pinterest.com/search/pins/?q=... format. Never /pin/ URLs.
2. References links: Always empty string "". We will add real URLs later.
3. Creative table references: Text descriptions ONLY. No URLs of any kind.
4. Violating these rules will cause the script to be rejected by QA.

Output ONLY valid JSON.`;

return [{ json: {
  prompt,
  brief,
  project_id,
  approved_concepts: approvedConcepts,
  concept_count: numConcepts,
  revision_count: ($input.first().json.revision_count || 0)
} }];

// ============================================================
// Build QA Agent prompt
// ============================================================

const writerOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const promptData = $('Build Writer Prompt').first().json;
const brief = promptData.brief;
const revisionCount = promptData.revision_count || 0;

const prompt = `REVIEW THESE UGC SCRIPTS. You are the final quality gate.

== COMPLIANCE RULES (NON-NEGOTIABLE) ==
Compliance Policy: ${brief.compliance || 'No specific compliance rules'}
Do NOT Say: ${brief.do_not_say || 'No restrictions'}

== BRAND CONTEXT ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature || 'N/A'}
Target: ${brief.target_user || 'N/A'}
Personality: ${brief.brand_personality || 'N/A'}

== SCRIPTS TO REVIEW ==
${writerOutput}

== YOUR REVIEW CHECKLIST ==
1. COMPLIANCE: Any 'do not say' violations? Unsubstantiated claims?
2. FRAMEWORK EXECUTION: Is each framework executed correctly?
3. HOOK QUALITY: Would a real person stop scrolling? Score 1-10.
4. AUTHENTICITY: Sounds like a real person or like ChatGPT?
5. AD PACING: Product reveal between 8-18 seconds?
6. PROOF SPECIFICITY: Numbers, timeframes, names — or vague?
7. CTA: Creates curiosity or is generic?
8. DIVERSITY: Different frameworks, hooks, voices across scripts?
9. HOOK VARIATIONS: Are there exactly 3 distinct hook variations? Different angles/energies?
10. CREATIVE TABLE: Does each scene have voiceover, visuals, and references? Minimum 4-5 scenes?
11. COSTUMES & PROPS: Are they specific and actionable? Could a creator shop for these items?
12. PRODUCTION READINESS: Could a creator film this script using only the brief?

== ADDITIONAL QUALITY TESTS (MANDATORY) ==
13. NATURAL SPEECH TEST: Read the full_script aloud. Does it sound like a real person talking or like AI-generated marketing copy? Real scripts have 'um', 'like', 'honestly', [beat], [pause], incomplete thoughts. If the script reads like a polished ad, it FAILS this test. Deduct 1 point.
14. SPECIFICITY TEST: Count specific numbers, timeframes, brand names, and sensory details in each script. Scripts with fewer than 3 specific details score MAX 6 regardless of other qualities. Vague scripts do not convert.
15. SCROLL-STOP TEST: Would the first 2 seconds make someone stop scrolling on TikTok? Be brutally honest. If the hook could apply to any brand or product, it fails. Deduct 2 points for generic hooks.

Output this JSON:
{
  "verdict": "APPROVED" or "NEEDS_REVISION",
  "overall_quality": 7.5,
  "revision_number": ${revisionCount},
  "script_reviews": [
    {
      "script_number": 1,
      "compliance_pass": true,
      "quality_score": 8,
      "issues": [],
      "revision_notes": ""
    }
  ],
  "batch_notes": "Overall assessment"
}

Revision #${revisionCount} of max 2. ${revisionCount >= 2 ? 'On revision 2+, approve ONLY if quality >= 6.5. Below 6.5, still mark NEEDS_REVISION with specific notes on what must change.' : ''}
Output ONLY valid JSON.`;

return [{ json: { prompt, brief, writer_output: writerOutput, revision_count: revisionCount, project_id: promptData.project_id, approved_concepts: promptData.approved_concepts } }];

// ============================================================
// Check QA Verdict — decision point
// ============================================================

const qaOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const prevData = $('Build QA Prompt').first().json;
const writerOutput = prevData.writer_output;
let revisionCount = prevData.revision_count || 0;

let qaResult;
try {
  qaResult = JSON.parse(qaOutput);
} catch(e) {
  const match = qaOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try { qaResult = JSON.parse(match[0]); } catch(e2) {
      qaResult = { verdict: 'APPROVED', batch_notes: 'Could not parse QA response, approving by default.' };
    }
  } else {
    qaResult = { verdict: 'APPROVED', batch_notes: 'Could not parse QA response, approving by default.' };
  }
}

const verdict = (qaResult.verdict || 'APPROVED').toUpperCase();
const needsRevision = verdict === 'NEEDS_REVISION' && revisionCount < 2;

return [{
  json: {
    verdict,
    needs_revision: needsRevision,
    revision_count: revisionCount + (needsRevision ? 1 : 0),
    revision_notes: qaResult.batch_notes || '',
    script_reviews: qaResult.script_reviews || [],
    overall_quality: qaResult.overall_quality || 0,
    writer_output: writerOutput,
    qa_output: qaOutput,
    project_id: prevData.project_id,
    brief: prevData.brief,
    approved_concepts: prevData.approved_concepts
  }
}];

// ============================================================
// Route back to Script Writer with revision context
// ============================================================

const verdict = $input.first().json;
const brief = verdict.brief;

const revisionFeedback = (verdict.script_reviews || []).map(r =>
  `Script ${r.script_number}: Score ${r.quality_score}/10${r.issues && r.issues.length ? ' — Issues: ' + r.issues.join(', ') : ''}${r.revision_notes ? ' — Notes: ' + r.revision_notes : ''}`
).join('\n');

const prompt = `REVISION REQUESTED — The QA agent has reviewed your scripts and sent them back.

== QA REVISION NOTES ==
${verdict.revision_notes}

== SCRIPT-LEVEL FEEDBACK ==
${revisionFeedback}

== ORIGINAL BRIEF ==
