// Match scripts to concepts by name or index
const scriptRecords = scripts.map((s, i) => {
  const conceptName = s.concept_name || '';
  const matchedConcept = approvedConcepts.find(c => c.concept_name === conceptName) || approvedConcepts[i] || {};

  // Extract 3 hook variations
  const hooks = Array.isArray(s.hooks) ? s.hooks : [s.hook || ''];
  const hook_1 = hooks[0] || s.hook || '';
  const hook_2 = hooks[1] || '';
  const hook_3 = hooks[2] || '';

  // Extract costumes, props, creative_table as JSON strings
  // === URL VALIDATION SAFETY NET ===
    // Clean costumes: ensure Pinterest links are search URLs, not pin URLs
    let cleanCostumes = [];
    if (Array.isArray(s.costumes)) {
      cleanCostumes = s.costumes.map(c => {
        let link = c.reference_link || '';
        // Convert pin URLs to search URLs
        if (link.includes('pinterest.com/pin/') || (link.includes('pinterest') && !link.includes('/search/'))) {
          const item = (c.item || '').replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/\s+/g, '+');
          link = 'https://pinterest.com/search/pins/?q=' + item;
        }
        // Ensure it's a valid Pinterest search URL or empty
        if (link && !link.includes('pinterest.com/search/')) {
          const item = (c.item || '').replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/\s+/g, '+');
          link = 'https://pinterest.com/search/pins/?q=' + item;
        }
        return { item: c.item || '', reference_link: link };
      });
    }
    const costumes = JSON.stringify(cleanCostumes);

    const props = Array.isArray(s.props) ? s.props.join(', ') : (s.props || '');

    // Clean creative_table: strip ALL URLs from references field
    let cleanCreativeTable = [];
    if (Array.isArray(s.creative_table)) {
      cleanCreativeTable = s.creative_table.map(scene => {
        let refs = scene.references || '';
        // Remove any URLs from references - keep only descriptive text
        refs = refs.replace(/https?:\/\/[^\s"',\]})]+/g, '').trim();
        if (!refs || refs === '""') refs = '[Style reference]';
        return { ...scene, references: refs };
      });
    }
    const creative_table_json = JSON.stringify(cleanCreativeTable);

    const concept_story = s.concept_story || '';

    // Clean references: remove fake URLs, keep descriptions
    let cleanRefs = [];
    if (Array.isArray(s.references)) {
      cleanRefs = s.references.map(r => ({
        description: r.description || '',
        link: '' // Always empty — real URLs added in delivery phase
      }));
    }
    const references = JSON.stringify(cleanRefs);

  return {
    project_id: project_id,
    concept_id: matchedConcept.id || '',
    script_number: s.script_number || (i + 1),
    hook: hook_1,
    hook_1: hook_1,
    hook_2: hook_2,
    hook_3: hook_3,
