    solution: s.solution || '',
    proof: s.proof || '',
    cta: s.cta || '',
    full_script: s.full_script || '',
    visual_direction: s.visual_direction || '',
    on_screen_text: Array.isArray(s.on_screen_text) ? s.on_screen_text.join(' | ') : (s.on_screen_text || ''),
    creator_notes: s.creator_notes || '',
    estimated_duration: s.estimated_duration || '30 sec',
    thumbnail_frame: s.thumbnail_frame || '',
    costumes: costumes,
    props: props,
    creative_table_json: creative_table_json,
    concept_story: concept_story,
    references_json: references,
    qa_score: qaQuality,
    pm_status: 'Pending',
    pm_notes: '',
    client_status: 'Pending',
    client_notes: '',
    overall_status: 'PM Review',
    version: 1,
    concept_name: s.concept_name || matchedConcept.concept_name || 'Concept ' + (i + 1),
    format: s.format || matchedConcept.format || 'UGC'
  };
});

